// Azure Functions (isolated worker): queue-triggered, idempotent, bounded concurrency set in host.json
public sealed class StatementRequestedFunction(IStatementService statements, IIdempotencyStore idem, ILogger<StatementRequestedFunction> log)
{
    [Function("StatementRequested")]
    public async Task Run([ServiceBusTrigger("statement-requests", Connection = "Bus")] ServiceBusReceivedMessage msg,
                          ServiceBusMessageActions actions, CancellationToken ct)
    {
        if (!await idem.TryStartAsync(msg.MessageId, TimeSpan.FromDays(1), ct)) { await actions.CompleteMessageAsync(msg, ct); return; }
        var req = msg.Body.ToObjectFromJson<StatementRequest>()!;
        await statements.GenerateAsync(req, ct);                       // writes PDF to blob storage, emits StatementReady
        await actions.CompleteMessageAsync(msg, ct);
        log.LogInformation("Statement {AccountId} {Month} generated", req.AccountId, req.Month);
    }
}
